(()=>{const t=window.BarfordMemberFlow,p=window.BarfordSupabase,a=document.getElementById("memberPayments"),n=new URLSearchParams(location.search).get("event");if(!t||!a)return;if(n){const r=document.getElementById("paymentBack");r.href=t.eventUrl(n),r.textContent="\u2190 Back to my event"}async function m(){try{const r=await t.request(p.auth.getSession());if(!r.session){a.innerHTML=`<article class="simple-card"><h2>Sign in to see your payments</h2><a class="button button-primary" href="${t.loginUrl(location.href)}">Sign in</a></article>`;return}const y=p.from("rsvps").select("event_id,status,payment_status,is_course_member").eq("member_id",r.session.user.id),c=await t.request(n?y.eq("event_id",n):y),h=n?[n]:c.filter(e=>e.status==="playing"||["paid","refunded","waived"].includes(e.payment_status)).map(e=>e.event_id);if(!h.length){a.innerHTML='<article class="simple-card"><h2>No event payments to show</h2><p>Your payments will appear here when you book an event.</p><a class="button button-primary" href="events.html">View events</a></article>';return}const o=await t.request(p.from("events").select("*").in("id",h).order("event_date"));if(!o.length){a.innerHTML='<article class="simple-card"><h2>Event not found</h2><a class="button button-outline" href="payments.html">View all my payments</a></article>';return}const i=t.paymentSummary(o,c),b=o.filter(e=>t.payment(e,c.find(s=>s.event_id===e.id)).due),l=o.filter(e=>!b.includes(e)),u=e=>{const s=c.find(f=>f.event_id===e.id),d=t.payment(e,s);return`<article class="simple-card payment-receipt"><p class="eyebrow">${t.esc(t.date(e.event_date))}</p><h2>${t.esc(e.name)}</h2><p>${t.esc(t.priceLabel(s))}</p><p class="simple-payment-state"><strong>${t.esc(d.label)}</strong></p>${d.due?"<p>Payment details are available from the committee. Your status changes to Paid when they confirm receipt.</p>":e.status==="cancelled"&&s?.payment_status==="paid"?"<p>Contact the committee to check your refund.</p>":s?.status==="reserve"?"<p>No payment is needed while you wait for a place.</p>":""}${d.due?`<button class="button button-primary full-button" data-payment-help="${t.esc(e.id)}">Get payment instructions</button><details class="simple-details"><summary>Already sent your payment?</summary><p>It has not been confirmed yet. Ask the committee to check before paying again.</p><button class="button button-outline" data-payment-check="${t.esc(e.id)}">Ask for confirmation</button></details>`:""}${s?.status==="playing"&&e.status==="scheduled"?`<a class="button button-outline full-button" href="${t.eventUrl(e.id)}#my-group">View my tee group \u2192</a><p>Your tee time and group appear there when announced.</p>`:""}<a class="simple-back" href="${t.eventUrl(e.id)}">Back to this event</a></article>`};a.innerHTML=`<section class="simple-card"><p class="eyebrow">${n?"This event":"My payments"}</p><h2>\xA3${(i.pence/100).toFixed(2)} outstanding</h2><p>${i.count?`${i.count} event${i.count===1?"":"s"} to pay.`:"No confirmed event fees outstanding."}${i.unpriced?` ${i.unpriced} booking${i.unpriced===1?" is":"s are"} awaiting a price.`:""}</p><button class="button button-outline" id="refreshPaymentStatus" type="button">Check payment status</button>${n?'<a class="simple-back" href="payments.html">All my payments</a>':""}</section>`+b.map(u).join("")+(l.length?n?l.map(u).join(""):`<details class="simple-card simple-details"><summary>Other bookings and payment history (${l.length})</summary><div class="simple-detail-content">${l.map(u).join("")}</div></details>`:""),a.querySelector("#refreshPaymentStatus").onclick=m,a.querySelectorAll("[data-payment-help],[data-payment-check]").forEach(e=>e.onclick=()=>t.contact(o.find(s=>s.id===(e.dataset.paymentHelp||e.dataset.paymentCheck)),e.dataset.paymentCheck?"check a payment I have already made":"get the payment details"))}catch{a.innerHTML='<article class="simple-card"><h2>Payments could not be checked</h2><p>Please try again to see the latest payment status.</p><button class="button button-primary" id="retryPayments">Try again</button></article>',a.querySelector("#retryPayments").onclick=m}}m()})();
